// src/lib/content/card-defaults.ts
// Starting text for a new CARD_ONLY draft, taken verbatim from the stored source (never generated by
// a model). It is only a prefill: an admin must review/edit it before the card can be published.

const clip = (text: string, max: number): string => {
  const t = text.replace(/\s+/g, ' ').trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, max);
  return `${cut.slice(0, Math.max(cut.lastIndexOf(' '), max / 2))}…`;
};

export function newsCardDefaults(story: { publisher: string; summary?: string | null }) {
  return {
    description: story.summary?.trim() ? clip(story.summary, 500) : null,
    attribution: `स्रोत: ${story.publisher}`.slice(0, 500),
  };
}

export function schemeCardDefaults(scheme: { department?: string | null; officialName: string; benefits: string[] }) {
  const benefits = scheme.benefits.filter((b) => b.trim()).join(' ');
  return {
    description: benefits ? clip(benefits, 500) : null,
    attribution: `स्रोत: ${scheme.department?.trim() || scheme.officialName}`.slice(0, 500),
  };
}
